// This file is automatically generated. Small, safe edits allowed to avoid crashing the app when env vars are missing.
import { createClient } from '@supabase/supabase-js';
import type { Database } from './types';
import { brokeredPreviewStorage } from './previewAuthStorage';

const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL;
const SUPABASE_PUBLISHABLE_KEY = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY;

function isNewSupabaseApiKey(value: string): boolean {
  return typeof value === 'string' && (value.startsWith('sb_publishable_') || value.startsWith('sb_secret_'));
}

function createSupabaseFetch(supabaseKey: string): typeof fetch {
  return (input, init) => {
    const headers = new Headers(
      typeof Request !== 'undefined' && input instanceof Request ? input.headers : undefined,
    );

    if (init?.headers) {
      new Headers(init.headers).forEach((value, key) => headers.set(key, value));
    }

    // New Supabase API keys are opaque strings, not bearer JWTs.
    // If an opaque key is used, remove any Bearer Authorization header so the API key is used.
    const authHeader = headers.get('Authorization');
    if (isNewSupabaseApiKey(supabaseKey) && typeof authHeader === 'string' && authHeader.toLowerCase().startsWith('bearer ')) {
      headers.delete('Authorization');
    }

    if (supabaseKey) headers.set('apikey', supabaseKey);
    return fetch(input, { ...init, headers });
  };
}

// When VITE_SUPABASE_* env vars are missing in the environment the real client will crash at module-eval time.
// Provide a safe fallback that preserves the shape enough for the app to boot and show degraded functionality,
// while logging a clear warning to the console.
function makeFallbackClient() {
  const warning = () => console.warn('[supabase] Supabase env vars not provided; running in degraded mode.');
  warning();

  const noopPromise = async () => ({ data: null, error: new Error('Supabase not configured') });

  const methodHandler: ProxyHandler<any> = {
    get: () => new Proxy(noopPromise, methodHandler),
    apply: () => noopPromise(),
  };

  // Return a very small proxy that responds to arbitrary method/property access with a noop promise.
  return new Proxy(() => {}, methodHandler) as unknown as any;
}

// Export supabase: either the real client (when both env vars are present) or the fallback proxy.
export const supabase = (
  SUPABASE_URL && SUPABASE_PUBLISHABLE_KEY
) ? createClient<Database>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
  global: {
    fetch: createSupabaseFetch(SUPABASE_PUBLISHABLE_KEY),
  },
  auth: {
    storage: brokeredPreviewStorage(),
    persistSession: true,
    autoRefreshToken: true,
  }
}) : makeFallbackClient();
